contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes memory data) public {
        uint beforeBal = address(c).balance;
        c.Command(address(c), data); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;
        assert(afterBal == beforeBal);
    }

    receive() external payable {}
}

