pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(bytes memory data) internal {
        uint beforeBal = address(c).balance;
        try c.Command(address(c), data) {} catch { return; }
        uint afterBal = address(c).balance;
        assertTrue(afterBal == beforeBal);
    }

    function testFuzz_run(bytes memory data) public {
        _run(data);
    }

    receive() external payable {}
}
